"$userbase/bin/caper" run   --backend local   --ignore-womtool   --local-out-dir "$PWD/smoke-out"   --local-loc-dir "$PWD/smoke-loc"   --max-concurrent-tasks 1   --disable-call-caching   --str-label encode_atac_cromwell_smoke   --cromwell-stdout "$PWD/cromwell.out"   -i "$PWD/hello.json"   "$PWD/hello.wdl" > smoke-run.log 2>&1 || run_status=$?
{
  echo RUN_STATUS
  echo "$run_status"
  echo CAPER_LOG
  cat smoke-run.log
  echo CROMWELL_LOG
  if test -f cromwell.out; then cat cromwell.out; fi
  echo FILES
  find "$PWD" -maxdepth 6 -type f -print
} > smoke-evidence.txt
test -s smoke-evidence.txt
